using System.Linq;using System;using System.IO;using System.Text;using System.Diagnostics;using System.Windows.Forms;using System.Drawing.Imaging;
namespace BeamScheduleFormatter {
static class ProfessionalReportExport {
 public static void Show(IWin32Window owner,EngineeringReport report){using(var dialog=new SaveFileDialog{Filter="Engineering report (*.html)|*.html",FileName="DTCE-Engineering-Report.html",OverwritePrompt=true})if(dialog.ShowDialog(owner)==DialogResult.OK){File.WriteAllText(dialog.FileName,report.Html(),new UTF8Encoding(false));Process.Start(new ProcessStartInfo(dialog.FileName){UseShellExecute=true});}}
 public static EngineeringReport FromText(string text){var p=ProjectInfoStore.Read();return ProfessionalReport.FromText(text,EstimatePdf.Heading(text),p.Name,p.Location,p.Office);}
}
partial class WindDesignForm {
 protected override EngineeringReport BuildEngineeringReport(){BuildReport();var p=ProjectInfoStore.Read();string image;using(var snapshot=siteMap.Snapshot())using(var output=new MemoryStream()){snapshot.Save(output,ImageFormat.Png);image=Convert.ToBase64String(output.ToArray());}return WindReportFile.Create(Number("Latitude"),Number("Longitude"),Value("Category"),Number("Height"),Number("Kd"),terrain,((CheckBox)Inputs["Reviewed"]).Checked,BuildingEnabled?Building():null,p.Name,p.Location,p.Office,image);}
}
partial class ProgramOfWorksForm {
 void ExportEngineeringReport(){ProfessionalReportExport.Show(this,BuildQuantityEngineeringReport());}
 string QuantityReportScope(){string scope=tabs.SelectedTab==null?"Bill of Quantities Summary":tabs.SelectedTab.Text;return scope=="Reports"?reportScope.Text:scope=="Bill of Quantities"?"Bill of Quantities Summary":scope;}
 bool MatchesQuantityScope(string scope,string section){if(scope=="Bill of Quantities Summary")return true;if(scope=="Reinforced Concrete Works")return section==scope||section=="Miscellaneous Structures";if(scope=="Earthworks")return section==scope||section=="Gravel";if(scope=="Structural Steel Works")return section==scope||section=="Steel purchase by profile"||section=="Sag Rods";if(scope=="Finishing Works")return section==scope||section=="Finish material breakdown"||section=="Railing";if(scope=="Doors & Windows")return section==scope||section=="Door / window schedule";return section==scope;}
 bool GridMatchesQuantityScope(string scope,Control grid){if(scope=="Bill of Quantities Summary")return true;for(Control c=grid;c!=null;c=c.Parent)if(c.Parent==tabs)return c.Text==scope;return false;}
 EngineeringReport BuildQuantityEngineeringReport(){
  Guard();Commit();Recalculate();var issues=WorksValidationIssues();UpdateDashboard();string scope=QuantityReportScope();bool overall=scope=="Bill of Quantities Summary",detailed=reportDetail.SelectedIndex>0,extensive=reportDetail.SelectedIndex==2;var p=ProjectInfoStore.Read();var report=ProfessionalReport.Create("Quantity take-off report",p.Name,p.Location,p.Office);report.Subtitle=scope+" · "+(extensive?"Extensive calculation record (with full calculation trace)":detailed?"Detailed calculation record":"Quantity summary");if(issues.Count>0){report.Status="Partial — "+issues.Count+" input issues";var review=report.Section("Input issues / omitted entries");review.Note("Valid quantities are included. Entries with invalid inputs are omitted from computed totals and retained in the POW file.");review.Table(new[]{"No.","Input issue"},issues.Select((issue,n)=>new[]{(n+1).ToString(),issue}));}
  if(overall){var summary=report.Section("Bill of Quantities");summary.Note("Source and measurement records explain the quantities below. They are supporting breakdowns, not additional quantities to add to the BOQ.");var values=new System.Collections.Generic.List<string[]>();foreach(DataGridViewRow row in boqGrid.Rows){if(row.IsNewRow||string.IsNullOrWhiteSpace(Convert.ToString(row.Cells[2].Value)))continue;if(row.Tag==null&&Convert.ToString(row.Cells[1].Value).StartsWith("    "))continue;values.Add(new[]{Convert.ToString(row.Cells[0].Value),Convert.ToString(row.Cells[1].Value),Convert.ToString(row.Cells[2].FormattedValue),Convert.ToString(row.Cells[3].Value)});}if(values.Count>0)summary.Table(new[]{"Pay item","Description","Quantity","Unit"},values);else summary.Note("No quantified items have been entered. Enter measurements or explicit BOQ quantities to generate the calculation record.");}
  foreach(var group in BillOfQuantities().Where(q=>MatchesQuantityScope(scope,q.Section)&&(Math.Abs(q.Quantity)>1e-10||q.Sources.Any(source=>Math.Abs(source.Quantity)>1e-10))).GroupBy(q=>q.Section)){
   var section=report.Section(group.Key);section.Table(new[]{"Material / work","Quantity","Unit"},group.Select(q=>new[]{q.Description,q.Quantity.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture),q.Unit}));
   if(detailed)foreach(var quantity in group){var sources=quantity.Sources.Where(source=>Math.Abs(source.Quantity)>1e-10).ToList();if(sources.Count==0)continue;section.Paragraph(quantity.Description+" — source breakdown");section.Table(new[]{"Source / member","Quantity","Unit","Calculation / basis"},sources.Select(source=>new[]{source.Description,source.Quantity.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture),source.Unit,source.Computation??""}));}
  }
  if(detailed){
  var reinforcement=(overall?projectRebarPlan.Concat(slopePlan).Distinct():scope=="Slope Protection Works"?slopePlan:projectRebarPlan.AsEnumerable()).Where(a=>a.Choice!=null).ToList();if((overall||scope=="Reinforced Concrete Works"||scope=="Slope Protection Works")&&reinforcement.Count>0){var steel=report.Section("Reinforcing steel — calculation record");steel.Note("Quantities are purchased stock weights. Compatible offcuts are shared internally; source allocations explain the purchase total and must not be added a second time.");steel.Table(new[]{"Source / member","Quantity","Unit","Calculation / basis"},reinforcement.Select(a=>new[]{RebarSource(a),a.Purchase.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture),"kg",(a.Line.Formula??"")+"; G"+a.Demand.Grade+", "+RebarDiameterText.Format(a.Demand.Diameter)+": "+a.Demand.Pieces+" × "+a.Demand.Cut.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)+" m × "+a.UnitMass.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)+" kg/m = "+a.Net.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)+" kg net; added lap "+a.Splice.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)+" kg; allocated offcut "+a.Waste.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)+" kg."}));}
  AddOffcutReuse(report,scope,overall,reinforcement); /* where reused offcuts come from (owner, 23 November 2026) */
  /* Extensive (owner, 19 November 2026: "wala naman pinagbago ang detailed at extensive"): the full bar-by-bar calculation trace and
     the commercial bars to order, after the Detailed calculation record */
  if(extensive&&(overall||scope=="Reinforced Concrete Works"||scope=="Slope Protection Works")&&reinforcement.Count>0){TakeoffEngineeringReports.Trace(report,"Reinforcing steel — calculation trace (Extensive)",reinforcement);
   var stocks=reinforcement.SelectMany(a=>a.Stocks).Distinct().ToList();if(stocks.Count>0)report.Section("Commercial bars to order (Extensive)").Table(new[]{"Grade / diameter / commercial length","Whole bars","Purchase kg"},stocks.GroupBy(x=>new{x.Grade,x.Diameter,x.Length}).OrderBy(g=>g.Key.Grade).ThenBy(g=>g.Key.Diameter).ThenBy(g=>g.Key.Length).Select(g=>new[]{"G"+g.Key.Grade+" / "+RebarDiameterText.Format(g.Key.Diameter)+" / "+g.Key.Length.ToString("0.##",System.Globalization.CultureInfo.InvariantCulture)+" m",g.Sum(x=>x.Count).ToString(System.Globalization.CultureInfo.InvariantCulture),g.Sum(x=>x.Length*x.Count*EstimatorEngine.UnitMass(x.Diameter)).ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)}));}
  var grids=Tables().Concat(extraGrids.Select(pair=>new System.Collections.Generic.KeyValuePair<string,DataGridView>(pair.Value.Kind,pair.Value.Grid))).Concat(new[]{new System.Collections.Generic.KeyValuePair<string,DataGridView>("Beam estimate",beam.WorksInputGrid),new System.Collections.Generic.KeyValuePair<string,DataGridView>("Slab estimate",slab.WorksInputGrid)});
  foreach(var table in grids){
   if(new[]{"RoofProfiles","InsulationRolls","FinishSchedule","PlumbingLS"}.Contains(table.Key))continue;var grid=table.Value;if(grid==null||grid.ReadOnly||!GridMatchesQuantityScope(scope,grid))continue;var rows=grid.Rows.Cast<DataGridViewRow>().Where(row=>!row.IsNewRow&&!Empty(row)).ToList();if(rows.Count==0)continue;
   var fields=grid.Columns.Cast<DataGridViewColumn>().Where(column=>column.Visible&&!column.ReadOnly).ToList();if(fields.Count==0)continue;var section=report.Section(System.Text.RegularExpressions.Regex.Replace(table.Key,"([a-z])([A-Z])","$1 $2")+" — measurement inputs");/* Compact (owner, 17 November 2026): one table per sheet, one line per record, instead of a heading and a two-column table per record. */var headers=grid.Columns.Cast<DataGridViewColumn>().Select(c=>c.HeaderText).ToArray();Func<DataGridViewRow,DataGridViewColumn,string> value=(row,column)=>RebarDiameterText.IsColumn(headers,column.Index)?RebarDiameterText.Format(row.Cells[column.Index].Value):Convert.ToString(row.Cells[column.Index].Value);var idColumn=grid.Columns[0];var descColumn=grid.Columns.Count>1?grid.Columns[1]:null;
   section.Table(new[]{"ID","Description","Inputs"},rows.Select(row=>new[]{Convert.ToString(row.Cells[idColumn.Index].Value),descColumn==null?"":Convert.ToString(row.Cells[descColumn.Index].Value),string.Join("; ",fields.Where(column=>column!=idColumn&&column!=descColumn&&!string.IsNullOrWhiteSpace(Convert.ToString(row.Cells[column.Index].Value))).Select(column=>column.HeaderText.Replace("\r"," ").Replace("\n"," ").Replace(" (auto)","")+" "+value(row,column)))}));
  }
  }
  if(report.Sections.Count==0)report.Section(scope).Note("No measured quantities have been entered for this scope.");
  return report;
 }
 void PreviewQuantityEngineeringReport(){CalculationPreview.Show(this,BuildQuantityEngineeringReport());}
 void SaveQuantityEngineeringPdf(){var report=BuildQuantityEngineeringReport();using(var dialog=new SaveFileDialog{Filter="PDF report (*.pdf)|*.pdf",FileName="DTCE-Quantity-Report.pdf",OverwritePrompt=true})if(dialog.ShowDialog(this)==DialogResult.OK)EngineeringQuantityPdf.WriteFlattened(dialog.FileName,report);}
}
}
